import React, { useEffect, useState } from "react";
import { motion } from "framer-motion";

function Profile() {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchProfile = async () => {
      try {
        const token = localStorage.getItem("token");
        const res = await fetch("http://localhost:5000/api/profile", {
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${token}`,
          },
        });

        if (!res.ok) throw new Error("Failed to fetch profile");

        const data = await res.json();
        setUser(data);
      } catch (err) {
        console.error(err);
      } finally {
        setLoading(false);
      }
    };

    fetchProfile();
  }, []);

  if (loading) {
    return (
      <div style={loadingStyle}>
        <motion.p
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ duration: 0.6, repeat: Infinity, repeatType: "reverse" }}
        >
          Loading profile...
        </motion.p>
      </div>
    );
  }

  if (!user) {
    return (
      <div style={loadingStyle}>
        <motion.p
          initial={{ y: -10, opacity: 0 }}
          animate={{ y: 0, opacity: 1 }}
          transition={{ duration: 0.5 }}
        >
          No profile data found
        </motion.p>
      </div>
    );
  }

  return (
    <div style={pageStyle}>
      <motion.div
        style={cardStyle}
        initial={{ y: -20, opacity: 0 }}
        animate={{ y: 0, opacity: 1 }}
        transition={{ duration: 0.7 }}
      >
        <h2 style={headingStyle}>👤 My Profile</h2>

        <motion.div
          style={infoContainer}
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 0.3, duration: 0.6 }}
        >
          <div style={infoBox}>
            <strong style={labelStyle}>Full Name:</strong>
            <p style={valueStyle}>{user.fullname}</p>
          </div>
          <div style={infoBox}>
            <strong style={labelStyle}>Email:</strong>
            <p style={valueStyle}>{user.email}</p>
          </div>
          <div style={infoBox}>
            <strong style={labelStyle}>Vehicle Number:</strong>
            <p style={valueStyle}>{user.vehiclenumber}</p>
          </div>
        </motion.div>
      </motion.div>
    </div>
  );
}

/* ---------- Styles ---------- */
const pageStyle = {
  minHeight: "100vh",
  display: "flex",
  alignItems: "center",
  justifyContent: "center",
  background: "linear-gradient(135deg, #2ceb25ff, #7715daff, #741dc4ff)",
  fontFamily: "Inter, sans-serif",
  padding: "1rem",
};

const cardStyle = {
  maxWidth: "420px", // reduced width
  width: "100%",
  padding: "1.5rem", // slightly smaller padding
  borderRadius: "14px",
  background: "#ffffff",
  boxShadow: "0 6px 20px rgba(0,0,0,0.12)",
};

const headingStyle = {
  textAlign: "center",
  marginBottom: "1.2rem",
  color: "#2563eb",
  fontSize: "1.5rem", // reduced size
  fontWeight: "700",
};

const infoContainer = {
  display: "flex",
  flexDirection: "column",
  gap: "1rem",
};

const infoBox = {
  padding: "0.8rem",
  borderRadius: "10px",
  background: "#f9fafb",
  boxShadow: "inset 0 1px 2px rgba(0,0,0,0.05)",
  transition: "all 0.3s ease",
};

const labelStyle = {
  display: "block",
  fontWeight: "600",
  color: "#374151",
  fontSize: "0.9rem",
};

const valueStyle = {
  marginTop: "0.25rem",
  fontSize: "1rem",
  color: "#111827",
};

const loadingStyle = {
  display: "flex",
  alignItems: "center",
  justifyContent: "center",
  minHeight: "100vh",
  fontSize: "1.1rem",
  fontWeight: "500",
  color: "#2563eb",
  fontFamily: "Inter, sans-serif",
};

export default Profile;
